def _instantiate_strategy(strategy_name: str, config: Dict[str, Any], timeframe: str, logger_obj: logging.Logger) -> Any:
    mapping = STRATEGY_CLASS_MAP.get(strategy_name)
    if not mapping:
        raise ValueError(f"Unknown strategy: {strategy_name}")
    
    class_name, module_name = mapping
    module = importlib.import_module(module_name)
    cls = getattr(module, class_name)
    
    reqs = _STRATEGY_HISTORY_REQUIREMENTS.get(strategy_name, {})
    final_config = {**config}
    final_config["hard_min_bars"] = reqs.get("hard_min_bars", 50)
    final_config["default_window"] = reqs.get("default_window", 200)
    
    return cls(config=final_config, timeframe=timeframe, logger=logger_obj)

def _get_component(component_name: str, config_override: Optional[Dict[str, Any]] = None) -> Any:
    """
    ✅ FIXED V3: Bulletproof Component Factory with Dynamic Name Resolution.
    
    Fixes:
    1. Trailing whitespace issues (e.g., 'BillWilliamsSuite ' -> 'BillWilliamsSuite').
    2. Case/Format mismatches (e.g., 'PivotPointsCalculator' -> 'pivot').
    3. Dynamic ingestion of STRATEGY_CLASS_MAP for future-proofing.
    """
    global _COMPONENT_REGISTRY, _COMPONENT_REGISTRY_LOCK
    
    # ─── 1. FAST PATH: CHECK CACHE ─────────────────────────────────────────────
    if _COMPONENT_REGISTRY is None:
        _COMPONENT_REGISTRY = {}
        
    with _COMPONENT_REGISTRY_LOCK:
        if component_name in _COMPONENT_REGISTRY:
            return _COMPONENT_REGISTRY[component_name]

    # ─── 2. INIT RESOLVER MAP (Singleton Pattern) ──────────────────────────────
    # Builds a comprehensive lookup table on first run to handle all naming variations.
    if not hasattr(_get_component, "_resolver_map"):
        import re
        
        def _to_snake_case(name: str) -> str:
            s1 = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', name)
            return re.sub('([a-z0-9])([A-Z])', r'\1_\2', s1).lower()

        resolver = {}
        
        # Canonical Definitions (Hardcoded Truth - No trailing spaces)
        canonical = {
            'price_action_engine': ('Strategy_management', 'PriceActionEngine'),
            'smart_money_engine': ('Strategy_management', 'SmartMoneyConceptsEngine'),
            'advanced_oscillators': ('Strategy_management', 'AdvancedOscillators'),
            'bill_williams': ('Strategy_management', 'BillWilliamsSuite'),
            'advanced_ma': ('Strategy_management', 'AdvancedMovingAverages'),
            'harmonic': ('Strategy_management', 'HarmonicPatternDetector'),
            'pivot': ('Strategy_management', 'PivotPointsCalculator'),
            'quant_methods': ('Strategy_management', 'QuantitativeMethods'),
            'mtf_engine': ('Strategy_management', 'MultiTimeframeConfluenceEngine'),
            'advanced_signal_strategies': ('Strategy_management', 'AdvancedSignalStrategies'),
            'crypto_indicators': ('Strategy_management', 'CryptoIndicators'),
            'divergence_analyzer': ('Strategy_management', 'DivergenceAnalyzer'),
            'volume_analyzer': ('Strategy_management', 'VolumeFlowAnalyzer'),
            'xgboost_signal_generator': ('Strategy_management', 'XGBoostSignalGenerator'),
            'technical_analyzer': ('Strategy_management', 'TechnicalAnalyzer'),
            'strategyscore_booster': ('Learning_signal_Management', 'StrategyScoreBooster'),
            'dynamic_weighting_system': ('Learning_signal_Management', 'DynamicWeightingSystem'),
            'signal_file_manager': ('Learning_signal_Management', 'SignalFileManager'),
            'strategypenalty_manager': ('Learning_signal_Management', 'StrategyPenaltyManager'),
        }
        
        for key, (mod, cls) in canonical.items():
            k_clean = str(key).strip().lower()
            c_clean = str(cls).strip().lower()
            
            # Map all variations: original, no_underscores, class_name, snake_case
            resolver[k_clean] = (mod, cls)
            resolver[k_clean.replace('_', '')] = (mod, cls)
            resolver[c_clean] = (mod, cls)
            resolver[c_clean.replace('_', '')] = (mod, cls)
            resolver[_to_snake_case(cls)] = (mod, cls)

        # Dynamic Ingestion from Strategy_management (Handles trailing spaces & new additions)
        try:
            from Strategy_management import STRATEGY_CLASS_MAP
            for k, v in STRATEGY_CLASS_MAP.items():
                if isinstance(v, (list, tuple)) and len(v) >= 2:
                    cls_name = str(v[0]).strip() # STRIP WHITESPACE HERE
                    mod_name = str(v[1]).strip()
                    k_clean = str(k).strip().lower()
                    
                    resolver[k_clean] = (mod_name, cls_name)
                    resolver[k_clean.replace('_', '')] = (mod_name, cls_name)
                    resolver[cls_name.lower()] = (mod_name, cls_name)
                    resolver[cls_name.lower().replace('_', '')] = (mod_name, cls_name)
                    resolver[_to_snake_case(cls_name)] = (mod_name, cls_name)
        except ImportError:
            pass
            
        _get_component._resolver_map = resolver

    # ─── 3. RESOLVE NAME ───────────────────────────────────────────────────────
    resolver_map = _get_component._resolver_map
    
    # Clean the input name
    clean_name = str(component_name).strip().lower().replace('-', '_').replace(' ', '_')
    clean_name_no_under = clean_name.replace('_', '')
    
    resolved = None
    if clean_name in resolver_map:
        resolved = resolver_map[clean_name]
    elif clean_name_no_under in resolver_map:
        resolved = resolver_map[clean_name_no_under]
        
    # Fallback: Substring/Fuzzy match if exact match fails
    if not resolved:
        for k, v in resolver_map.items():
            if clean_name_no_under in k or k in clean_name_no_under:
                resolved = v
                break

    if not resolved:
        logger.error(f"[COMPONENT_FACTORY] ❌ Unknown component: '{component_name}'. Cannot resolve to any known mapping.")
        return None

    module_name, class_name = resolved

    # ─── 4. INSTANTIATE & CACHE ────────────────────────────────────────────────
    try:
        import importlib
        module = importlib.import_module(module_name)
        
        # getattr will now succeed because class_name is stripped of trailing spaces
        cls = getattr(module, class_name)
        
        init_kwargs = config_override or {}
        
        # Auto-wire dependencies if needed
        if 'strategyscore_booster' in clean_name or 'strategyscorebooster' in clean_name_no_under:
            init_kwargs.setdefault('signal_file_manager', _get_component('signal_file_manager'))
            
        instance = cls(**init_kwargs)
        
        with _COMPONENT_REGISTRY_LOCK:
            _COMPONENT_REGISTRY[component_name] = instance
            # Also cache under the resolved clean name for faster future lookups
            if clean_name != component_name:
                _COMPONENT_REGISTRY[clean_name] = instance
                
        logger.debug(f"[COMPONENT_FACTORY] ✅ Instantiated {class_name} for '{component_name}'")
        return instance
        
    except AttributeError as e:
        logger.error(f"[COMPONENT_FACTORY] ❌ Attribute error: Module '{module_name}' has no attribute '{class_name}'. Check the class name in the source file.")
        return None
    except Exception as e:
        logger.error(f"[COMPONENT_FACTORY] ❌ Failed to instantiate {class_name} from {module_name}: {e}", exc_info=True)
        return None
        
async def _initialize_global_components() -> None:
    """
    ✅ FIXED: حالا این تابع فقط یک Wrapper است که _get_component را برای همه استراتژی‌ها فراخوانی می‌کند.
    این کار تضمین می‌کند که تمام کامپوننت‌ها با منطق یکسان و بدون Race Condition مقداردهی می‌شوند.
    """
    phase = "INIT_GLOBAL_COMPONENTS_UNIFIED"
    try:
        from Strategy_management import STRATEGY_CLASSES
        
        logger.info(f"[{phase}] 🚀 Initializing all strategies via unified factory...")
        for strategy_name in STRATEGY_CLASSES.keys():
            # فراخوانی _get_component باعث ساخت و کش شدن با min_bars صحیح می‌شود
            comp = _get_component(strategy_name)
            if comp is not None:
                logger.debug(f"[{phase}] ✅ {strategy_name} initialized successfully")
            else:
                logger.warning(f"[{phase}] ⚠️ Failed to initialize {strategy_name}")
                
        logger.info(f"[{phase}] ✅ Global component initialization complete")
    except Exception as e:
        logger.error(f"[{phase}] ❌ Critical error during global initialization: {e}", exc_info=True)
        
def _component_registry_get(key: str, factory, *, ttl_seconds: Optional[float] = None):
    now = time.time()
    entry = _COMPONENT_REGISTRY.get(key)
    if entry is not None:
        obj, created_at = entry
        if ttl_seconds is None or (now - created_at) < float(ttl_seconds):
            return obj

    with _COMPONENT_REGISTRY_LOCK:
        entry = _COMPONENT_REGISTRY.get(key)
        if entry is not None:
            obj, created_at = entry
            if ttl_seconds is None or (time.time() - created_at) < float(ttl_seconds):
                return obj
        try:
            obj = factory()
        except Exception as exc:
            logger.error("Component '%s' construction failed: %s", key, exc, exc_info=True)
            return None
        if obj is None:
            logger.error("Component '%s' factory returned None", key)
            return None
        _COMPONENT_REGISTRY[key] = (obj, time.time())
        logger.info("Component '%s' initialized (%s)", key, type(obj).__name__)
        return obj

def _get_or_createsignal_file_manager(base_dir: Optional[str] = None):
    """
    ✅ FIXED V2: مسیر پیش‌فرض بر اساس محل فایل پروژه، نه os.getcwd().
    این رفع می‌کند که فایل‌ها در مسیر اشتباه (مثلاً CWD/signals/) ذخیره شوند.
    """
    cached = _COMPONENT_CACHE.get('signal_file_manager')
    if cached is not None:
        return cached

    # ✅ مسیر ریشه را از محل خود فایل بگیر، نه از cwd
    project_root = Path(__file__).resolve().parent
    if base_dir:
        root = Path(base_dir)
    else:
        root = Path(os.environ.get(
            "SIGNAL_STORE_DIR",
            str(project_root / "TRADE" / "SIGNALS")
        ))

    try:
        from Learning_signal_Management import SignalFileManager
    except Exception as exc:
        logger.error(f"[SFM_INIT] Import failed: {exc}", exc_info=True)
        return None

    root.mkdir(parents=True, exist_ok=True)
    strategies_dir = root.parent / "STRATEGIES"
    metadata_dir = root.parent / "METADATA"
    strategies_dir.mkdir(parents=True, exist_ok=True)
    metadata_dir.mkdir(parents=True, exist_ok=True)

    try:
        instance = SignalFileManager(
            signals_dir=str(root),
            strategies_dir=str(strategies_dir),
            metadata_dir=str(metadata_dir),
        )
    except TypeError:
        instance = SignalFileManager(signals_dir=str(root))

    # ✅ این attribute را ذخیره می‌کنیم تا PenaltyManager و CLE هم ببینند
    instance.base_dir = str(project_root)
    _COMPONENT_CACHE['signal_file_manager'] = instance
    logger.info(f"[SFM_INIT] ✅ SignalFileManager created at: {root}")
    return instance
    
