class _AnalysisCacheManager:
    def __init__(self, max_items: Optional[int] = None, default_ttl: float = 300.0):
        self._lock = threading.RLock()
        import collections
        self._store = collections.OrderedDict()
        self._default_ttl = float(default_ttl) if default_ttl and default_ttl > 0 else 300.0
        self._hits = 0
        self._misses = 0
        self._max_items = int(max_items) if max_items else self._autosize()

    @staticmethod
    def _autosize() -> int:
        total_gb = 2.0
        try:
            import psutil
            total_gb = float(psutil.virtual_memory().total) / (1024.0 ** 3)
        except Exception:
            try:
                pages = os.sysconf("SC_PHYS_PAGES")
                page_size = os.sysconf("SC_PAGE_SIZE")
                total_gb = float(pages * page_size) / (1024.0 ** 3)
            except (ValueError, OSError, AttributeError):
                total_gb = 2.0
        return int(max(128, min(8192, round(total_gb * 64))))

    def _purge_expired_locked(self, now: float) -> None:
        dead = [k for k, (_, exp) in self._store.items() if exp <= now]
        for k in dead:
            self._store.pop(k, None)

    def get(self, key: str, default: Any = None) -> Any:
        if not key:
            return default
        now = time.time()
        with self._lock:
            entry = self._store.get(key)
            if entry is None:
                self._misses += 1
                return default
            value, expires_at = entry
            if expires_at <= now:
                self._store.pop(key, None)
                self._misses += 1
                return default
            self._store.move_to_end(key)
            self._hits += 1
            return value

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> bool:
        if not key:
            return False
        ttl_val = float(ttl) if (ttl is not None and ttl > 0) else self._default_ttl
        now = time.time()
        try:
            with self._lock:
                self._store[key] = (value, now + ttl_val)
                self._store.move_to_end(key)
                self._purge_expired_locked(now)
                while len(self._store) > self._max_items:
                    self._store.popitem(last=False)
            return True
        except Exception as exc:
            logger.warning("Cache set failed for '%s': %s", key, exc)
            return False

    put = set
    store = set

    def delete(self, key: str) -> bool:
        with self._lock:
            return self._store.pop(key, None) is not None

    def clear(self) -> int:
        with self._lock:
            n = len(self._store)
            self._store.clear()
            return n

_cache_manager: Optional[_AnalysisCacheManager] = None

def _get_cache_manager() -> _AnalysisCacheManager:
    global _cache_manager
    if _cache_manager is None:
        with _COMPONENT_REGISTRY_LOCK:
            if _cache_manager is None:
                _cache_manager = _AnalysisCacheManager()
                logger.info("Analysis cache ready (capacity=%d)", _cache_manager._max_items)
    return _cache_manager

