def _get_hardware_identifier() -> str:
    """
    تولید شناسه یکتای سخت‌افزار با استفاده از HardwareProfile
    
    Returns:
        str: شناسه کوتاه سخت‌افزار (مثلاً 'HW_A1B2C3')
    """
    phase = "GET_HARDWARE_IDENTIFIER"
    
    try:
        # ✅ استفاده از تابع موجود detect_hardware_profile
        profile = detect_hardware_profile()
        
        # ترکیب اطلاعات کلیدی برای تولید شناسه یکتا
        hardware_parts = [
            profile.cpu_name[:8].strip() if profile.cpu_name else "CPU",
            str(profile.cpu_physical_cores),
            str(round(profile.ram_gb / 2, 0) * 2),  # RAM به نزدیک‌ترین عدد زوج
        ]
        
        # تولید هش از ترکیب اطلاعات
        raw_string = "_".join(hardware_parts)
        hash_bytes = hashlib.sha256(raw_string.encode()).digest()[:3]
        hash_hex = hash_bytes.hex().upper()
        
        hw_id = f"HW_{hash_hex}"
        
        logger.info(f"[{phase}] ✅ Hardware ID generated: {hw_id} (CPU: {profile.cpu_name[:20]}...)")
        return hw_id
        
    except Exception as e:
        logger.error(f"[{phase}] ❌ Error generating hardware ID: {e}")
        # Fallback: استفاده از platform و hostname
        try:
            import platform
            import socket
            fallback_id = f"HW_{platform.node()[:6].upper()}_{platform.processor()[:4].upper()}"
            return fallback_id[:10]  # محدود کردن طول
        except:
            return "HW_DEFAULT"


def get_hardware_identifier_sync() -> str:
    """
    نسخه همگام (Sync) برای استفاده در توابع غیرasync
    
    Returns:
        str: شناسه سخت‌افزار
    """
    try:
        profile = detect_hardware_profile()
        
        hardware_parts = [
            profile.cpu_name[:8].strip() if profile.cpu_name else "CPU",
            str(profile.cpu_physical_cores),
            str(round(profile.ram_gb / 2, 0) * 2),
        ]
        
        raw_string = "_".join(hardware_parts)
        hash_bytes = hashlib.sha256(raw_string.encode()).digest()[:3]
        hash_hex = hash_bytes.hex().upper()
        
        return f"HW_{hash_hex}"
        
    except Exception:
        try:
            import platform
            import socket
            return f"HW_{platform.node()[:6].upper()}"
        except:
            return "HW_DEFAULT"

def _infer_hold_quality_from_context(
    reason: str,
    is_fallback: bool = False,
    error_type: str = "None",
) -> float:
    """
    کیفیت تصمیم HOLD را از متن reason استنتاج می‌کند.

    Mapping:
      - خطای واقعی + insufficient data → 0.55 (مشکل در دسترس‌بودن داده، باگ نیست)
      - خطای واقعی (باگ)              → 0.30
      - No setup / gate rejected       → 0.78
      - Regime-suppressed hold         → 0.82
      - Insufficient بدون خطا          → 0.60
      - Default analytical hold        → 0.70

    Returns:
        float: hold_quality ∈ [0.30, 0.90]
    """
    try:
        r = str(reason or "").lower()
        et = str(error_type or "None").lower()

        if is_fallback or et not in ("none", "", "null"):
            if any(k in r for k in (
                "insufficient data", "insufficient history",
                "insufficient bars", "not enough data",
                "too few bars", "validation failed",
                "missing columns", "too much nan",
            )):
                return 0.55
            return 0.30

        if not r or r in ("n/a", "none", "unknown"):
            return 0.60

        if any(k in r for k in (
            "no clear", "no setup", "no qualified", "no high-quality",
            "no valid", "no dominant", "no aligned", "no significant",
            "no patterns", "no harmonic patterns",
            "insufficient confluence", "below", "gate rejected",
            "insufficient agreement", "weak agreement",
            "conflict", "conflicting",
        )):
            return 0.78

        if any(k in r for k in (
            "ranging", "suppressed", "regime", "range bound",
            "sideways", "quiet", "low volatility", "dead",
        )):
            return 0.82

        if any(k in r for k in (
            "insufficient", "not enough", "too few",
            "short history", "warm-up", "cold start",
        )):
            return 0.60

        return 0.70
    except Exception:
        return 0.60

def _derive_hold_confidence(
    hold_quality: float,
    regime_confidence: float,
    regime_adx: float = 20.0,
) -> float:
    """
    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║         DERIVE HOLD CONFIDENCE — V2.0 (HONEST, EMPIRICALLY BOUNDED)         ║
    ║                                                                              ║
    ║  🔴 BUG FIXED (v1 → v2):                                                     ║
    ║    • v1 می‌توانست تا 0.70 برسد، و همین مقدار به‌عنوان «confidence»           ║
    ║      سیگنال HOLD در aggregation شرکت می‌کرد، سپس در `_aggregate_             ║
    ║      strategy_results` با جهت‌دارها وزن‌دهی می‌شد و WR را آلوده می‌کرد.     ║
    ║    • v2 سقف را به 0.55 کاهش می‌دهد (طبق تعریف، «اطمینان به درست بودن      ║
    ║      تصمیم به عدم ورود» هرگز نباید با confidence یک BUY قابل مقایسه        ║
    ║      باشد)، و مؤلفه‌ی ADX را که منبع تورم مصنوعی بود حذف می‌کند.           ║
    ║    • خروجی همیشه در [0.25, 0.55] است.                                       ║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """
    try:
        hq = float(hold_quality)
    except (TypeError, ValueError):
        hq = 0.60
    if not np.isfinite(hq):
        hq = 0.60
    hq = min(max(hq, 0.0), 1.0)

    try:
        rc = float(regime_confidence)
    except (TypeError, ValueError):
        rc = 0.5
    if not np.isfinite(rc):
        rc = 0.5
    rc = min(max(rc, 0.0), 1.0)

    # NOTE: regime_adx عمداً دیگر در فرمول وارد نمی‌شود.
    #       ADX بالا به‌معنای «روند قوی» است، نه «HOLD باکیفیت‌تر».
    #       پارامتر برای سازگاری امضای عمومی حفظ شده است.
    _ = regime_adx

    # فرمول جدید: فقط دو مؤلفه، با سقف سخت 0.55
    conf = 0.25 + 0.22 * hq + 0.08 * rc
    return float(min(max(conf, 0.25), 0.55))
    
async def _invoke_analyze_all_variants(
    component: Any,
    kwargs_chain,
    label: str,
    phase_tag: str = "EXECUTOR",
):
    """
    متد analyze_all کامپوننت را با اولین امضای سازگار از kwargs_chain صدا می‌زند.

    Args:
        component: نمونهٔ استراتژی (دارای متد analyze_all)
        kwargs_chain: لیست (variant_name, kwargs_dict) به‌ترتیب اولویت
        label: نام نمایشی برای لاگ
        phase_tag: پیشوند لاگ

    Returns:
        خروجی نرمال‌نشدهٔ analyze_all (dict یا object)
    """
    fn = getattr(component, "analyze_all", None)
    if fn is None or not callable(fn):
        raise AttributeError(f"{label}: 'analyze_all' method not found")
    is_async = asyncio.iscoroutinefunction(fn)
    last_type_error = None
    for variant_name, kwargs in kwargs_chain:
        try:
            if is_async:
                result = await fn(**kwargs)
            else:
                result = await asyncio.to_thread(fn, **kwargs)
            if asyncio.iscoroutine(result):
                logger.warning(f"[{phase_tag}] ⚠️ {label}: result was a leaked coroutine — awaiting")
                result = await result
            return result
        except TypeError as te:
            msg = str(te)
            if ("unexpected keyword argument" in msg
                    or "positional argument" in msg
                    or "required positional" in msg):
                logger.debug(f"[{phase_tag}] ⚠️ {label}: signature variant '{variant_name}' incompatible → next: {te}")
                last_type_error = te
                continue
            raise
    if last_type_error is not None:
        raise last_type_error
    raise TypeError(f"{label}: no compatible analyze_all signature found")

def atomic_write_text(path: str, content: str, max_retries: int = 5) -> bool:
    """
    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║         ATOMIC WRITE TEXT - V2 (FIXED: OS-LEVEL FILE LOCKING)              ║
    ║                      ✅ FIXED: Prevents summary.txt corruption             ║
    ║                      ✅ OPTIMIZED: Exponential backoff on lock contention  ║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """
    if not path:
        return False
        
    directory = os.path.dirname(os.path.abspath(path))
    tmp_path = None
    
    try:
        os.makedirs(directory, exist_ok=True)
        
        for attempt in range(max_retries):
            try:
                # ایجاد فایل موقت یکتا
                fd, tmp_path = tempfile.mkstemp(prefix=".tmp_summary_", dir=directory, text=True)
                
                # ✅ OS-LEVEL LOCKING
                import platform
                if platform.system() == 'Windows':
                    import msvcrt
                    try:
                        msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
                    except OSError:
                        os.close(fd)
                        os.unlink(tmp_path)
                        tmp_path = None
                        time.sleep(0.5 * (2 ** attempt))  # Exponential backoff
                        continue
                else:
                    import fcntl
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    except BlockingIOError:
                        os.close(fd)
                        os.unlink(tmp_path)
                        tmp_path = None
                        time.sleep(0.5 * (2 ** attempt))  # Exponential backoff
                        continue
                
                # نوشتن محتوا
                with os.fdopen(fd, 'w', encoding='utf-8') as fh:
                    fh.write(content)
                    fh.flush()
                    os.fsync(fh.fileno())
                    
                # ✅ ATOMIC REPLACE
                os.replace(tmp_path, path)
                return True
                
            except (OSError, IOError) as e:
                if tmp_path and os.path.exists(tmp_path):
                    try:
                        os.unlink(tmp_path)
                    except OSError:
                        pass
                    tmp_path = None
                    
                if attempt == max_retries - 1:
                    logger.error(f"[ATOMIC_WRITE] Failed after {max_retries} retries: {e}")
                    return False
                    
                time.sleep(0.5 * (2 ** attempt))
                
        return False
        
    except Exception as e:
        logger.error(f"[ATOMIC_WRITE] Critical error: {e}")
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
        return False
        
def cleanup_poisoned_signals_from_disk(signals_dir: str = "TRADE/SIGNALS") -> int:
    """
    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║    CLEANUP POISONED SIGNALS FROM DISK                                      ║
    ║    ✅ FIXED: Physically deletes JSON files marked as poisoned/failed       ║
    ║    ✅ OPTIMIZED: Batch processing with minimal I/O overhead                ║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """
    phase = "CLEANUP_POISONED_SIGNALS"
    deleted_count = 0
    
    try:
        base_dir = Path(signals_dir)
        if not base_dir.exists():
            return 0
            
        # جستجو در تمام زیرپوشه‌ها (TP, SL, PENDING, etc.)
        for json_file in base_dir.rglob("*.json"):
            try:
                with open(json_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    
                # بررسی شرایط سمی بودن
                is_poisoned = data.get('is_poisoned', False)
                status = data.get('status', '')
                confidence = data.get('confidence', 1.0)
                
                # اگر سمی است یا وضعیت خطا دارد و کانفیدنس پایین است (fallback)
                if is_poisoned or status == 'ERROR' or (status == 'HOLD' and confidence <= 0.55):
                    json_file.unlink()
                    deleted_count += 1
                    
            except (json.JSONDecodeError, OSError, KeyError):
                # اگر فایل خراب است، آن را حذف کن
                try:
                    json_file.unlink()
                    deleted_count += 1
                except OSError:
                    pass
            except Exception:
                # سایر خطاها را نادیده بگیر تا حلقه متوقف نشود
                pass
                
        if deleted_count > 0:
            logger.info(f"[{phase}] 🧹 Cleaned {deleted_count} poisoned/failed signal files from disk")
            
        return deleted_count
        
    except Exception as e:
        logger.error(f"[{phase}] ❌ Cleanup error: {e}", exc_info=True)
        return 0          
@dataclass
class LiveTradeSignal:
    """سیگنال نهایی معاملاتی با تمام متادیتا"""
    signal: str
    confidence: float
    timestamp: datetime
    symbol: str
    timeframe: str
    current_price: float
    model_signal: str
    model_confidence: float
    ta_signal: str
    ta_confidence: float
    model_weight: float
    ta_weight: float
    stop_loss: float
    take_profit: float
    position_size: float
    reasons: List[str] = field(default_factory=list)
