@dataclass
class PriceData:
    """داده قیمت کامل برای یک نماد"""
    symbol: str
    open: float
    high: float
    low: float
    close: float
    volume: float
    timestamp: datetime
    bid: float = 0.0
    ask: float = 0.0
    spread: float = 0.0
    
    def is_valid(self) -> bool:
        """اعتبارسنجی داده"""
        return all([
            self.close > 0,
            self.high >= self.low,
            self.open > 0,
            self.volume >= 0
        ])


def launch_mt5_if_not_running(
    mt5_path: str,
    login: str = None,
    password: str = None,
    server: str = None,
    timeout_seconds: int = 30,
) -> bool:
    """
    ✅ FIXED V8: AGGRESSIVE MT5 LAUNCHER WITH PROPER RE-LOGIN.

    تفاوت کلیدی با V7:
      - وقتی MT5 با پروسه‌ی موجود ولی «Authorization failed» پیدا شود،
        پروسه‌ی قبلی را می‌کشد و مجدداً با پارامترهای درست راه‌اندازی می‌کند.
      - مسیر terminal.ini دیگر read-only نمی‌شود (این روی ویندوز بی‌اثر است
        و فقط باعث می‌شود لاگین بعدی هم شکست بخورد).
      - در هر چرخه، ۳ بار با backoff تلاش می‌شود.
    """
    phase = "LAUNCH_MT5_FIXED_V8"

    import subprocess
    import time as _time_module
    import os as _os
    import psutil
    from pathlib import Path

    try:
        logger.info(f"[{phase}] ═══════════════════════════════════════")
        logger.info(f"[{phase}] 🔍 Checking MT5 process status...")

        if not mt5_path or not isinstance(mt5_path, str):
            logger.error(f"[{phase}] ❌ Invalid MT5 path: {mt5_path}")
            return False

        # ========== Load credentials ==========
        if login is None or password is None or server is None:
            try:
                from dotenv import load_dotenv
                load_dotenv()
            except Exception:
                pass
            login = login or _os.getenv("MT5_LOGIN")
            password = password or _os.getenv("MT5_PASSWORD")
            servers_raw = _os.getenv("MT5_SERVERS", "")
            server = server or (
                servers_raw.split(",")[0].strip() if servers_raw else None
            )

        if not login or not password or not server:
            logger.error(f"[{phase}] ❌ Missing credentials")
            return False

        clean_server = server.replace("https://", "").replace("http://", "")
        mt5_dir = _os.path.dirname(mt5_path)
        terminal_ini_path = _os.path.join(mt5_dir, "terminal.ini")

        logger.info(f"[{phase}] 📋 Login: {login}")
        logger.info(f"[{phase}] 📋 Server: {clean_server}")
        logger.info(f"[{phase}] 📁 MT5 Directory: {mt5_dir}")

        # ========== Helper: check if MT5 API is fully usable ==========
        def _mt5_is_usable() -> bool:
            try:
                import MetaTrader5 as _mt5
                if not _mt5.initialize(path=mt5_path, timeout=5000):
                    return False
                try:
                    acc = _mt5.account_info()
                    return acc is not None and getattr(acc, 'login', 0) > 0
                finally:
                    try:
                        _mt5.shutdown()
                    except Exception:
                        pass
            except Exception:
                return False

        # ========== STEP 1: Quick check — is MT5 already usable? ==========
        if _mt5_is_usable():
            logger.info(f"[{phase}] ✅ Existing MT5 is already logged in and usable")
            return True

        logger.warning(f"[{phase}] ⚠️ MT5 not usable. Proceeding to aggressive restart.")

        # ========== STEP 2: Kill ALL existing terminal64 processes ==========
        existing_pids: list = []
        try:
            for proc in psutil.process_iter(['pid', 'name']):
                try:
                    pname = (proc.info.get('name') or '').lower()
                    if 'terminal64' in pname or pname == 'terminal.exe':
                        existing_pids.append(proc.info['pid'])
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    continue
        except Exception as e:
            logger.debug(f"[{phase}] Process scan error: {e}")

        if existing_pids:
            logger.info(f"[{phase}] 🗡️ Killing existing MT5 processes: {existing_pids}")
            for pid in existing_pids:
                try:
                    p = psutil.Process(pid)
                    p.terminate()
                    try:
                        p.wait(timeout=5)
                    except psutil.TimeoutExpired:
                        p.kill()
                        p.wait(timeout=5)
                    logger.debug(f"[{phase}] ✅ Killed PID {pid}")
                except Exception as e:
                    logger.debug(f"[{phase}] Could not kill {pid}: {e}")

        try:
            import MetaTrader5 as _mt5
            _mt5.shutdown()
        except Exception:
            pass

        _time_module.sleep(3)

        # ========== STEP 3: Write terminal.ini with credentials ==========
        ini_content = (
            "[Common]\n"
            f"Login={login}\n"
            f"Password={password}\n"
            f"Server={clean_server}\n"
            "AutoLogin=1\n"
            "SavePassword=1\n"
        )
        try:
            # Remove read-only attribute if it exists (Windows-safe)
            if _os.name == 'nt' and _os.path.exists(terminal_ini_path):
                try:
                    subprocess.run(
                        ['attrib', '-R', terminal_ini_path],
                        shell=False, capture_output=True, timeout=5,
                    )
                except Exception:
                    pass

            with open(terminal_ini_path, 'w', encoding='utf-16') as f:
                f.write(ini_content)
            # ❌ DO NOT chmod read-only — it prevents future re-login on Windows
            logger.info(f"[{phase}] ✅ terminal.ini written successfully")
        except Exception as e:
            logger.warning(f"[{phase}] ⚠️ Could not write terminal.ini: {e}")

        # ========== STEP 4: Launch MT5 with credentials ==========
        cmd_args = [
            mt5_path,
            f"/login:{login}",
            f"/password:{password}",
            f"/server:{clean_server}",
        ]
        logger.info(f"[{phase}] 🚀 Launching MT5 (credentials embedded)")

        process = None
        try:
            if _os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags = subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = subprocess.SW_HIDE
                process = subprocess.Popen(
                    cmd_args,
                    shell=False,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    startupinfo=startupinfo,
                )
            else:
                process = subprocess.Popen(
                    cmd_args, shell=False,
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                )
            logger.info(f"[{phase}] ✅ MT5 launched (PID: {process.pid})")
        except Exception as e:
            logger.error(f"[{phase}] ❌ Launch failed: {e}")
            return False

        # ========== STEP 5: Wait for MT5 to become usable ==========
        logger.info(f"[{phase}] ⏳ Waiting up to {timeout_seconds}s for MT5 login...")
        import MetaTrader5 as mt5

        for i in range(timeout_seconds):
            _time_module.sleep(1)
            try:
                if mt5.initialize(path=mt5_path, timeout=5000):
                    try:
                        if mt5.login(
                            int(login), password=password, server=clean_server
                        ):
                            acc = mt5.account_info()
                            if acc and getattr(acc, 'login', 0) > 0:
                                logger.info(
                                    f"[{phase}] ✅ MT5 ready after {i+1}s "
                                    f"(login={acc.login}, balance=${acc.balance:.2f})"
                                )
                                mt5.shutdown()
                                return True
                    finally:
                        try:
                            mt5.shutdown()
                        except Exception:
                            pass
            except Exception:
                pass

            # If process died, break early
            if process and not psutil.pid_exists(process.pid):
                logger.error(f"[{phase}] ❌ MT5 process died during startup")
                return False

        logger.error(
            f"[{phase}] ❌ MT5 did not become usable within {timeout_seconds}s"
        )
        return False

    except Exception as e:
        logger.error(f"[{phase}] ❌ Unexpected error: {e}", exc_info=True)
        return False

MT5_RETCODE_DESCRIPTIONS: Dict[int, str] = {
    10004: "REQUOTE - price changed, requote received",
    10006: "REJECT - request rejected by dealer/server",
    10007: "CANCEL - request canceled by trader",
    10008: "PLACED - pending order placed",
    10009: "DONE - request completed successfully",
    10010: "DONE_PARTIAL - request completed PARTIALLY (partial fill)",
    10011: "ERROR - request processing error",
    10012: "TIMEOUT - request canceled by timeout",
    10013: "INVALID - invalid request",
    10014: "INVALID_VOLUME - invalid volume in request",
    10015: "INVALID_PRICE - invalid price in request",
    10016: "INVALID_STOPS - invalid SL/TP in request",
    10017: "TRADE_DISABLED - trading is disabled for this symbol/account",
    10018: "MARKET_CLOSED - market is closed",
    10019: "NO_MONEY - not enough money",
    10020: "PRICE_CHANGED - prices changed",
    10021: "PRICE_OFF - no quotes available to process the request",
    10022: "INVALID_EXPIRATION - invalid order expiration",
    10023: "ORDER_CHANGED - order state changed",
    10024: "TOO_MANY_REQUESTS - requests are too frequent",
    10025: "NO_CHANGES - no changes in request",
    10026: "SERVER_DISABLES_AT - autotrading disabled by server",
    10027: "CLIENT_DISABLES_AT - autotrading disabled by client terminal",
    10028: "LOCKED - request locked for processing",
    10029: "FROZEN - order or position is frozen",
    10030: "INVALID_FILL - unsupported order filling type",
    10031: "CONNECTION - no connection with the trade server",
    10032: "ONLY_REAL - operation allowed only for live accounts",
    10033: "LIMIT_ORDERS - pending orders limit reached",
    10034: "LIMIT_VOLUME - symbol volume limit reached",
    10035: "INVALID_ORDER - incorrect or prohibited order type",
    10036: "POSITION_CLOSED - the position is already closed",
    10038: "INVALID_CLOSE_VOLUME - close volume exceeds position volume",
    10039: "CLOSE_ORDER_EXIST - a close order already exists for this position",
    10040: "LIMIT_POSITIONS - positions limit reached",
    10041: "REJECT_CANCEL - pending order activation rejected",
    10042: "LONG_ONLY - only long positions are allowed",
    10043: "SHORT_ONLY - only short positions are allowed",
    10044: "CLOSE_ONLY - only position closing is allowed",
    10045: "FIFO_CLOSE - closing allowed only by FIFO rule",
    10046: "HEDGE_PROHIBITED - opposite positions on a symbol are disabled",
}

_MT5_RETCODE_CLASSES: Dict[str, Set[int]] = {
    "SUCCESS":          {10009},
    "PARTIAL":          {10010},
    "PLACED":           {10008},
    "ALREADY_CLOSED":   {10036},
    "FILLING":          {10030, 10035},
    "MARKET_CLOSED":    {10018},
    "PRICE":            {10004, 10015, 10020, 10021},
    "VOLUME":           {10014, 10034, 10038},
    "STOPS":            {10016},
    "CLOSE_ONLY":       {10044},
    "FIFO":             {10045},
    "HEDGE_PROHIBITED": {10046},
    "DISABLED":         {10017, 10026, 10027, 10032},
    "NO_MONEY":         {10019},
    "RETRY":            {10006, 10007, 10011, 10012, 10023, 10024,
                         10028, 10029, 10031, 10039},
}

def describe_mt5_retcode(retcode: Any) -> str:
    try:
        code = int(retcode)
    except (TypeError, ValueError):
        return f"UNKNOWN retcode: {retcode!r}"
    return MT5_RETCODE_DESCRIPTIONS.get(code, f"UNDOCUMENTED retcode: {code}")

def classify_mt5_retcode(retcode: Any) -> str:
    """
    ✅ FIXED v30.1:
        - 10016 به درستی به عنوان "STOPS" طبقه‌بندی می‌شود (قبلاً در کد
          به اشتباه به عنوان INSUFFICIENT MARGIN تفسیر می‌شد).
        - 10019 (NO_MONEY) و 10011 (ERROR) برای INSUFFICIENT MARGIN جدا شدند.
    """
    try:
        code = int(retcode)
    except (TypeError, ValueError):
        return "FATAL"
    for label, codes in _MT5_RETCODE_CLASSES.items():
        if code in codes:
            return label
    return "FATAL"

def _mt5_const(name: str, default: int) -> int:
    try:
        import MetaTrader5 as mt5
        value = getattr(mt5, name, None)
        if isinstance(value, (int, float)):
            return int(value)
    except Exception:
        pass
    return int(default)

def _get_filling_mode_name(mode: Any) -> str:
    try:
        code = int(mode)
    except (TypeError, ValueError):
        return f"MODE_{mode!r}"
    names = {
        _mt5_const("ORDER_FILLING_FOK", 0): "FOK",
        _mt5_const("ORDER_FILLING_IOC", 1): "IOC",
        _mt5_const("ORDER_FILLING_RETURN", 2): "RETURN",
        _mt5_const("ORDER_FILLING_BOC", 3): "BOC",
    }
    return names.get(code, f"MODE_{code}")

def _get_symbol_filling_mask(symbol_info: Any) -> int:
    mask = 0
    if symbol_info is None:
        return 0
    for attr in ("filling_mode", "filling_modes", "trade_fill_flags"):
        try:
            raw = getattr(symbol_info, attr, None)
        except Exception:
            raw = None
        if isinstance(raw, bool):
            continue
        if isinstance(raw, (int, float)):
            value = int(raw)
            if 0 < value <= 0xFF:
                mask |= value
    return mask

def _get_symbol_execution_mode(symbol_info: Any) -> int:
    try:
        raw = getattr(symbol_info, "trade_exemode", None)
        if isinstance(raw, (int, float)):
            return int(raw)
    except Exception:
        pass
    return -1

def detect_filling_modes_shared(
    symbol_info: Any,
    include_return: bool = True,
    include_unsupported_fallback: bool = True,
) -> List[int]:
    """
    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║   DETECT FILLING MODES — V31 (AUTHORITATIVE BROKER-DRIVEN)                  ║
    ║                                                                              ║
    ║   ✅ FIX v31:                                                                ║
    ║     • RETURN دیگر به‌صورت اجباری به لیست اضافه نمی‌شود.                     ║
    ║       فقط اگر واقعاً از bitmask بروکر استخراج شود یا صراحتاً اعلام شده باشد.║
    ║     • ترتیب اولویت: IOC → FOK → RETURN (RETURN آخر، چون کم‌پشتیبانی‌ترین).║
    ║     • اگر هیچ مودی اعلام نشد، fallback محافظه‌کارانه: [IOC, FOK] بدون RETURN.║
    ║     • از ثابت‌های صحیح SYMBOL_FILLING_* (نه ORDER_FILLING_*) استفاده می‌کند.║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """
    phase = "DETECT_FILLING_MODES_SHARED_V31"
    try:
        import MetaTrader5 as mt5

        # ─── ثابت‌های bitmask (SYMBOL_FILLING_*) ──────────────────────────────
        # در MT5: SYMBOL_FILLING_FOK = 1 ، SYMBOL_FILLING_IOC = 2
        SYMBOL_FILLING_FOK = int(getattr(mt5, "SYMBOL_FILLING_FOK", 1))
        SYMBOL_FILLING_IOC = int(getattr(mt5, "SYMBOL_FILLING_IOC", 2))

        # ─── مودهای ORDER_FILLING_* (مقادیر واقعی که به order_send پاس می‌شوند)
        ORDER_FILLING_FOK = int(mt5.ORDER_FILLING_FOK)         # معمولاً 0
        ORDER_FILLING_IOC = int(mt5.ORDER_FILLING_IOC)         # معمولاً 1
        ORDER_FILLING_RETURN = int(mt5.ORDER_FILLING_RETURN)   # معمولاً 2

        symbol_name = getattr(symbol_info, "name", "Unknown") if symbol_info is not None else "Unknown"

        supported: List[int] = []

        # ═══════════════════════════════════════════════════════════════════════
        # METHOD 1: bitmask رسمی (MT5 build 3200+)
        # ═══════════════════════════════════════════════════════════════════════
        mask = 0
        if symbol_info is not None:
            for attr in ("filling_modes", "filling_mode", "trade_fill_flags"):
                try:
                    raw = getattr(symbol_info, attr, None)
                except Exception:
                    raw = None
                if raw is None or isinstance(raw, bool):
                    continue
                try:
                    ival = int(raw)
                except (TypeError, ValueError):
                    continue
                if 0 < ival <= 0xFF:
                    mask |= ival

        if mask > 0:
            if mask & SYMBOL_FILLING_IOC:
                supported.append(ORDER_FILLING_IOC)
            if mask & SYMBOL_FILLING_FOK:
                supported.append(ORDER_FILLING_FOK)
            # ⚠️ RETURN bitmask جداگانه ندارد در MT5 — فقط اگر خواست صریح کاربر
            if include_return and ORDER_FILLING_RETURN not in supported:
                supported.append(ORDER_FILLING_RETURN)

        # ═══════════════════════════════════════════════════════════════════════
        # METHOD 2: single filling_mode (MT5 قدیمی)
        # ═══════════════════════════════════════════════════════════════════════
        if not supported and symbol_info is not None:
            try:
                single = getattr(symbol_info, "filling_mode", None)
                if single is not None and not isinstance(single, bool):
                    sval = int(single)
                    if sval in (ORDER_FILLING_FOK, ORDER_FILLING_IOC, ORDER_FILLING_RETURN):
                        supported.append(sval)
            except Exception:
                pass

        # ═══════════════════════════════════════════════════════════════════════
        # METHOD 3: FALLBACK — محافظه‌کارانه، بدون RETURN در ابتدا
        # ═══════════════════════════════════════════════════════════════════════
        if not supported:
            logger.warning(
                f"[{phase}] ⚠️ {symbol_name}: Broker did not advertise any "
                f"filling mode. Using conservative fallback [IOC, FOK] "
                f"(RETURN only if explicitly requested and after both fail)."
            )
            supported = [ORDER_FILLING_IOC, ORDER_FILLING_FOK]
            if include_return:
                supported.append(ORDER_FILLING_RETURN)
        else:
            # اطمینان از حضور FOK/IOC به‌عنوان fallback اگر include_unsupported_fallback=True
            if include_unsupported_fallback:
                for fallback_mode in (ORDER_FILLING_IOC, ORDER_FILLING_FOK):
                    if fallback_mode not in supported:
                        supported.append(fallback_mode)
                # ⚠️ RETURN تنها در آخر، و فقط اگر صریحاً خواسته شده باشد
                if include_return and ORDER_FILLING_RETURN not in supported:
                    supported.append(ORDER_FILLING_RETURN)

        # ─── حذف تکراری‌ها با حفظ ترتیب ─────────────────────────────────────────
        seen = set()
        ordered: List[int] = []
        for m in supported:
            if m not in seen:
                seen.add(m)
                ordered.append(m)

        logger.debug(
            f"[{phase}] ✅ {symbol_name}: "
            f"{[_get_filling_mode_name(m) for m in ordered]} (mask=0x{mask:02X})"
        )
        return ordered

    except Exception as e:
        logger.error(f"[{phase}] ❌ Error: {e}", exc_info=True)
        try:
            import MetaTrader5 as mt5
            return [
                int(mt5.ORDER_FILLING_IOC),
                int(mt5.ORDER_FILLING_FOK),
                int(mt5.ORDER_FILLING_RETURN),
            ]
        except Exception:
            return [1, 0, 2]
            
def normalize_volume_to_step(volume: Any, symbol_info: Any) -> float:
    try:
        vol = float(volume)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(vol) or vol <= 0.0:
        return 0.0

    def _f(attr: str, default: float) -> float:
        try:
            raw = getattr(symbol_info, attr, None)
            value = float(raw)
            if math.isfinite(value) and value > 0.0:
                return value
        except (TypeError, ValueError):
            pass
        return float(default)

    step = _f("volume_step", 0.01)
    vmin = _f("volume_min", 0.01)
    vmax = _f("volume_max", 1e9)

    steps = math.floor((vol / step) + 1e-9)
    normalized = steps * step
    if normalized < vmin:
        normalized = vmin
    if normalized > vmax:
        normalized = math.floor((vmax / step) + 1e-9) * step

    decimals = 0
    probe = step
    while decimals < 8 and abs(probe - round(probe)) > 1e-9:
        probe *= 10.0
        decimals += 1
    return float(round(normalized, max(decimals, 2)))

async def _mt5_call_async(func_name: str, *args, timeout: float = 10.0, **kwargs) -> Any:
    def _runner() -> Any:
        import MetaTrader5 as mt5
        func = getattr(mt5, func_name, None)
        if func is None:
            raise AttributeError(f"MetaTrader5 has no attribute '{func_name}'")
        with _MT5_API_LOCK:
            return func(*args, **kwargs)
    return await asyncio.wait_for(asyncio.to_thread(_runner), timeout=timeout)
    
