class ModelCandidate:
    """
    ساختار داده برای یک مدل کاندید
    
    ✅ FIXED: افزودن فیلدهای live_results و verification_method
    """
    def __init__(self, path: str, model_type: str, architecture: str, epoch: int = 0):
        self.path = path
        self.model_type = model_type  # 'checkpoint', 'edge', 'ensemble'
        self.architecture = architecture  # 'MH_Transformer', 'MH_WaveNet', etc.
        self.epoch = epoch
        
        # نتایج ارزیابی
        self.evaluation_results: Optional[Dict] = None
        self.live_results: Optional[Dict] = None  # ✅ NEW: ذخیره نتایج لایو
        self.verification_method: Optional[str] = None  # ✅ NEW: روش تأیید
        self.overall_confidence: float = 0.0  # ✅ NEW: اطمینان ترکیبی
        self.score: float = 0.0
        self.is_valid: bool = False
        self.verification_passed: bool = False
        self.live_test_passed: bool = False
        self.live_weight: float = 0.0  # وزن درصدی برای استفاده در ترید
        self.model_collapsed: bool = False  # ✅ NEW: وضعیت کلاپس
        
    def __repr__(self):
        return (f"ModelCandidate({self.architecture}, epoch={self.epoch}, "
                f"score={self.score:.3f}, weight={self.live_weight:.2%}, "
                f"confidence={self.overall_confidence:.2%}, collapsed={self.model_collapsed})")
                
