        self._symbol_cache_dir.mkdir(parents=True, exist_ok=True)
        self._symbol_cache: Dict[str, Dict] = {}
        self._symbol_cache_loaded: bool = False
        self._invalid_symbols: Set[str] = set()
        self._symbol_cache_ttl: int = 3600
        
        # ========== ✅ NEW: بارگذاری کش از فایل ==========
