                 symbol: str = None,
                 timeframe: str = None,
                 metadata_fold: int = None,
                 model_weight: float = 0.0,
                 stop_loss: float = None,
                 take_profit: float = None,
                 trailing_stop_pct: float = None,
                 profit_lock_pct: float = 0.01,
                 min_confidence: float = None,  # ✅ Now receives dynamic value
                 trade_interval_seconds: int = 300,
                 max_positions: int = 100,
                 position_size_pct: float = None,
                 max_risk_per_trade: float = 0.02,
                 max_daily_loss_pct: float = 0.05,
                 risk_level: str = "MODERATE",
                 drawdown_protection: str = "MODERATE",
                 max_portfolio_correlation: float = 0.30,
                 enable_stress_testing: bool = True,
                 enable_live_chart: bool = False,
                 live_chart_port: int = 8050,
                 enable_economic_calendar: bool = True,
                 multi_symbol_enabled: bool = True,
                 timeframes: List[str] = None,
