        self.cooldown_normal_seconds = 600
        self.cooldown_weak_seconds = 900
        self.cooldown_hold_seconds = 60
        self.max_consecutive_holds = 5
        self.cooldown_after_trade_seconds = 120
        self.min_final_score_normal = 45.0
        self.MIN_CONFIDENCE_THRESHOLD = _MIN_CONFIDENCE_THRESHOLD
