        self.regime_risk_multipliers = {"PANIC": 0.40, "NORMAL": 1.00, "RANGE": 0.70}
        self.sl_multipliers = {"NORMAL": 1.5, "RANGE": 1.8, "PANIC": 2.5}
        self.demo_volume_multiplier = 1.0
        self.live_volume_multiplier = 0.75
        self.volume_reduction_on_margin_error = 0.5
        self.volume_reduction_on_consecutive_loss = 0.3
        self.max_margin_usage_pct = 0.15
        self.min_margin_usage_pct = 0.01
        self.margin_safety_factor = 0.85
        self.max_volume_percent_of_symbol_max = 0.10
        self.min_volume_percent_of_symbol_max = 0.01
        self.min_sl_distance_pct = 0.005
        self.min_rr_ratio = 1.5
        self.min_rr_ratio_demo = 1.0
        self.min_rr_ratio_live = 1.5
        self.tp_sl_ratio = 2.0
