        report_lines.append(f"║  📡 Signal: {final_signal}")
        report_lines.append(f"║  🎯 Confidence: {confidence:.2%}")
        report_lines.append(f"║  📊 Total Score: {total_score:.1f}/100")
        report_lines.append(f"║  🌍 Market Regime: {regime} (Conf: {regime_conf:.0%})")
        report_lines.append(f"║  🔄 Range Market: {'Yes' if is_range else 'No'}")
        report_lines.append("╠══════════════════════════════════════════════════════════════╣")
        report_lines.append("║                                                              ║")
        report_lines.append("║  🏗️ STRUCTURE ANALYSIS                                        ║")
        report_lines.append("║  ────────────────────────────────────────────────────────── ║")
        report_lines.append(f"║     Signal: {structure.get('signal', 'HOLD')}")
        report_lines.append(f"║     Confidence: {structure.get('confidence', 0.0):.2%}")
        report_lines.append(f"║     Reason: {str(structure.get('reason', 'N/A'))[:40]}")
        report_lines.append("║                                                              ║")
        report_lines.append("║  📊 VOLUME ANALYSIS                                           ║")
        report_lines.append("║  ────────────────────────────────────────────────────────── ║")
        report_lines.append(f"║     Signal: {volume.get('signal', 'HOLD')}")
        report_lines.append(f"║     Confidence: {volume.get('confidence', 0.0):.2%}")
        vol_ratio = volume.get('volume_ratio', volume.get('details', {}).get('volume_ratio', 1.0))
        report_lines.append(f"║     Volume Ratio: {vol_ratio:.2f}x")
        report_lines.append("║                                                              ║")
        report_lines.append("║  🔄 DIVERGENCE ANALYSIS                                       ║")
        report_lines.append("║  ────────────────────────────────────────────────────────── ║")
        report_lines.append(f"║     Signal: {divergence.get('signal', 'HOLD')}")
        report_lines.append(f"║     Confidence: {divergence.get('confidence', 0.0):.2%}")
        report_lines.append(f"║     Reason: {str(divergence.get('reason', 'N/A'))[:40]}")
        report_lines.append("║                                                              ║")
        report_lines.append("║  🕯️ PATTERN ANALYSIS                                          ║")
        report_lines.append("║  ────────────────────────────────────────────────────────── ║")
        report_lines.append(f"║     Signal: {patterns.get('signal', 'HOLD')}")
        report_lines.append(f"║     Confidence: {patterns.get('confidence', 0.0):.2%}")
        report_lines.append(f"║     Active Count: {patterns.get('active_count', 0)}")
        report_lines.append("║                                                              ║")
        report_lines.append("║  🧠 STRATEGY OVERVIEW                                         ║")
        report_lines.append("║  ────────────────────────────────────────────────────────── ║")
        report_lines.append(f"║     Active Strategies: {active_strategies} / {len(strategy_details)}")
        
        # Aggregate strategy signals
        buy_signals = sum(1 for s in strategy_details.values() if isinstance(s, dict) and s.get('signal') in ['BUY', 'STRONG_BUY', 'WEAK_BUY'])
        sell_signals = sum(1 for s in strategy_details.values() if isinstance(s, dict) and s.get('signal') in ['SELL', 'STRONG_SELL', 'WEAK_SELL'])
        hold_signals = sum(1 for s in strategy_details.values() if isinstance(s, dict) and s.get('signal') in ['HOLD', 'STRONG_HOLD'])
        
        report_lines.append(f"║     🟢 Buy Signals: {buy_signals}")
