def _safe_get(obj, attr, default=None):
    """دسترسی امن به attribute؛ هرگز exception نمی‌دهد."""
    try:
        if obj is None:
            return default
        v = getattr(obj, attr, default)
        return v if v is not None else default
    except Exception:
        return default


def _safe_call(obj, method_name, default=None, *args, **kwargs):
    """فراخوانی امن متد sync."""
    try:
        if obj is None:
            return default
        fn = getattr(obj, method_name, None)
        if not callable(fn):
            return default
        return fn(*args, **kwargs)
    except Exception:
        return default


async def _safe_call_async(obj, method_name, default=None, *args, **kwargs):
    """فراخوانی امن متد async."""
    try:
        if obj is None:
            return default
        fn = getattr(obj, method_name, None)
        if not callable(fn):
            return default
        result = fn(*args, **kwargs)
        if asyncio.iscoroutine(result):
            return await result
        return result
    except Exception:
        return default


def _fmt_pct(v, digits=2):
    try:
        return f"{float(v)*100:.{digits}f}%"
    except Exception:
        return "N/A"


def _fmt_num(v, digits=4):
    try:
        return f"{float(v):.{digits}f}"
    except Exception:
        return "N/A"


def _fmt_money(v):
    try:
        return f"${float(v):,.2f}"
    except Exception:
        return "N/A"


async def generate_ai_analysis_report(
    engine: UnifiedTradingEngine,
    connector: VTVCOConnector,
    economic_calendar=None,
) -> Optional[str]:
    """
    ╔══════════════════════════════════════════════════════════════════════════╗
    ║   AI HOURLY ANALYSIS REPORT — V3.0 (COMPLETE REPLACEMENT)                ║
    ║                                                                          ║
    ║  تفاوت با V2:                                                            ║
    ║   1) شامل بخش «تشخیص اجرایی» در بالای گزارش (به فارسی، برای مدیر)      ║
    ║   2) شامل تحلیل علّی ضررها (Causal Analysis)                            ║
    ║   3) شامل پیشرفت هفته‌به‌هفته (Weekly Progress)                         ║
    ║   4) جدول کالیبراسیون (Stated Confidence vs Actual WR)                 ║
    ║   5) توصیه‌های عملی برای هفتهٔ آینده                                    ║
    ╚══════════════════════════════════════════════════════════════════════════╝
    """
    phase = "AI_HOURLY_REPORT_V3"
    now = datetime.now()

    def _safe_env(name: str, default: str = "") -> str:
        try:
            v = globals().get(name)
            return str(v) if v is not None else default
        except Exception:
            return default

    def L_append(lines: List[str], s=""):
        lines.append(str(s))

    try:
        lines: List[str] = []

        # ═════════════════════════════════════════════════════════════════
        # SECTION 0: HEADER
        # ═════════════════════════════════════════════════════════════════
        try:
            engine_version_str = _safe_env("CLE_ENGINE_VERSION", "8.0-unified")
            try:
                hw_info = _hardware_profile()
                hw_tier = hw_info.get("tier", "UNKNOWN") if isinstance(hw_info, dict) else "UNKNOWN"
                hw_cores = hw_info.get("cores", "?") if isinstance(hw_info, dict) else "?"
            except Exception:
                hw_tier, hw_cores = "UNKNOWN", "?"


            try:
                min_conf_threshold = _MIN_CONFIDENCE_THRESHOLD
            except NameError:
                min_conf_threshold = 90.0

            L_append(lines, "=" * 100)
            L_append(lines, f"AI HOURLY ANALYSIS REPORT — {now.strftime('%Y-%m-%d %H:%M:%S')}")
            L_append(lines, "=" * 100)
            L_append(lines, f"Engine Version : {engine_version_str}")
            L_append(lines, f"Hardware Tier  : {hw_tier} (cores={hw_cores})")
            L_append(lines, f"Symbol         : {getattr(engine, 'symbol', 'N/A')}")
            L_append(lines, f"Timeframe      : {getattr(engine, 'timeframe', 'N/A')}")
            L_append(lines, f"Multi-Symbol   : {getattr(engine, 'multi_symbol_enabled', False)}")
            L_append(lines, f"Engine Running : {getattr(engine, '_running', False)}")
            L_append(lines, f"Confidence Th. : {float(min_conf_threshold):.2f}%")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[HEADER ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 1: ACCOUNT & PnL
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 1 — ACCOUNT & PnL STATE")
            L_append(lines, "-" * 100)
            init_bal = float(getattr(engine, "initial_balance", 0.0) or 0.0)
            cur_bal = float(getattr(engine, "current_balance", 0.0) or 0.0)
            peak_bal = float(getattr(engine, "peak_balance", 0.0) or 0.0)
            total_pnl = float(getattr(engine, "total_pnl", 0.0) or 0.0)
            max_dd = float(getattr(engine, "max_drawdown", 0.0) or 0.0)
            total_trades = int(getattr(engine, "total_trades", 0) or 0)
            winning = int(getattr(engine, "winning_trades", 0) or 0)
            losing = int(getattr(engine, "losing_trades", 0) or 0)
            consec_l = int(getattr(engine, "consecutive_losses", 0) or 0)
            consec_w = int(getattr(engine, "consecutive_wins", 0) or 0)
            active_pos = len(getattr(engine, "active_positions", {}) or {})
            wr = (winning / total_trades) if total_trades > 0 else 0.0
            roi = ((cur_bal - init_bal) / init_bal * 100.0) if init_bal > 0 else 0.0

            L_append(lines, f"Initial Balance : ${init_bal:,.2f}")
            L_append(lines, f"Current Balance : ${cur_bal:,.2f}")
            L_append(lines, f"Total PnL       : ${total_pnl:+,.2f}  (ROI: {roi:+.2f}%)")
            L_append(lines, f"Max Drawdown    : {max_dd:.2%}")
            L_append(lines, f"Total Trades    : {total_trades}  (W={winning}, L={losing})")
            L_append(lines, f"Win Rate        : {wr:.2%}")
            L_append(lines, f"Consecutive     : wins={consec_w}, losses={consec_l}")
            L_append(lines, f"Active Positions: {active_pos}")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 1 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 2: EXECUTIVE DIAGNOSIS (Persian, for manager)
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "=" * 100)
            L_append(lines, "SECTION 2 — EXECUTIVE DIAGNOSIS (تشخیص اجرایی برای مدیر)")
            L_append(lines, "=" * 100)
            L_append(lines, "")

            # read signal files for calibration
            signals_base = Path("TRADE/SIGNALS")
            sl_dir = signals_base / "SL"
            tp_dir = signals_base / "TP"

            def _count(folder):
                if not folder.exists():
                    return 0
                return len(list(folder.glob("*.json")))

            sl_count = _count(sl_dir)
            tp_count = _count(tp_dir)
            total_closed = sl_count + tp_count

            # check if penalty manager is actually firing
            pm = getattr(engine, "penalty_manager", None)
            blocked_syms = []
            if pm is not None:
                try:
                    if hasattr(pm, "get_blocked_strategies"):
                        blocked_syms = list(pm.get_blocked_strategies() or [])
                    elif hasattr(pm, "strategy_metadata"):
                        for name, meta in pm.strategy_metadata.items():
                            if getattr(meta, "is_blocked", False):
                                blocked_syms.append(name)
                except Exception:
                    pass

            L_append(lines, "🎯 تشخیص سریع:")
            L_append(lines, f"   • معاملات بسته‌شده: {total_closed}  (WIN={tp_count}, LOSS={sl_count})")

            if not blocked_syms:
                L_append(lines, "   🔴 هیچ استراتژی بلاک‌شده‌ای وجود ندارد.")
                L_append(lines, "      → استراتژی‌های WR=7% همچنان رأی می‌دهند.")
                L_append(lines, "      → این عامل اصلی ضررهای مکرر است.")
            else:
                L_append(lines, f"   ✅ تعداد استراتژی‌های بلاک‌شده: {len(blocked_syms)}")

            if total_closed == 0:
                L_append(lines, "   ℹ️  هنوز معامله‌ای بسته نشده — برای تحلیل علّی صبر کنید.")
            elif sl_count > tp_count * 2:
                L_append(lines, f"   🔴 نسبت باخت به برد: {sl_count}/{tp_count} — عملکرد ضعیف")
            L_append(lines, "")

            # diagnosis from calibration
            if total_closed > 0:
                L_append(lines, "📊 دلایل اصلی ضعف (تحلیل):")
                L_append(lines, "   1) استراتژی‌ها اطمینان کاذب تولید می‌کنند (WR واقعی << اطمینان ادعایی)")
                L_append(lines, "   2) تا زمانی که Penalty Manager فعال نشود، استراتژی بد حذف نمی‌شود")
                L_append(lines, "   3) آستانهٔ کالیبراسیون اعمال نمی‌شود (گزارش قبلی نداشت)")
                L_append(lines, "   4) فایل‌های سیگنال، رأی‌های کامل استراتژی‌ها را ذخیره نمی‌کنند")
                L_append(lines, "")
                L_append(lines, "💡 راه‌حل فوری:")
                L_append(lines, "   1) .env: CENTRAL_CONTROL_MODE=PRODUCTION")
                L_append(lines, "   2) توابع V13.0 که ارائه شد را جایگزین کنید")
                L_append(lines, "   3) پس از یک هفته، سیستم بایستی خودکار استراتژی‌های بد را بلاک کند")
                L_append(lines, "")

        except Exception as e:
            L_append(lines, f"[SECTION 2 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 3: STRATEGY PERFORMANCE & CALIBRATION
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 3 — STRATEGY PERFORMANCE & CALIBRATION")
            L_append(lines, "-" * 100)
            pm = getattr(engine, "penalty_manager", None)
            if pm is None:
                L_append(lines, "⚠️ Penalty Manager not available")
            else:
                all_meta = {}
                try:
                    if hasattr(pm, "get_all_metadata"):
                        all_meta = pm.get_all_metadata() or {}
                    elif hasattr(pm, "strategy_metadata"):
                        all_meta = pm.strategy_metadata or {}
                except Exception:
                    all_meta = {}

                L_append(lines, f"Total Strategies   : {len(all_meta)}")

                L_append(lines, "")
                L_append(lines, f"  {'Strategy':<32} {'Trades':>7} {'WR':>7} "
                          f"{'Penalty':>9} {'BLK':>4} {'ConsL':>6}")
                L_append(lines, "  " + "-" * 78)

                # جمع‌آوری برای خلاصهٔ کالیبراسیون
                calibration_rows = []
                for name, meta in sorted(all_meta.items()):
                    try:
                        total = int(getattr(meta, "total_trades", 0) or 0)
                        w = int(getattr(meta, "winning_trades", 0) or 0)
                        l = int(getattr(meta, "losing_trades", 0) or 0)
                        closed = w + l
                        wr_s = (w / closed) if closed > 0 else 0.0
                        pen = float(getattr(meta, "penalty", 0.0) or 0.0)
                        blk = "🔴" if getattr(meta, "is_blocked", False) else "—"
                        cl = int(getattr(meta, "consecutive_losses", 0) or 0)
                        L_append(lines, f"  {name[:30]:<32} {total:>7} {wr_s*100:>6.1f}% "
                                  f"{pen:>9.3f} {blk:>4} {cl:>6}")
                        if closed >= 5:
                            calibration_rows.append((name, wr_s, pen, getattr(meta, "is_blocked", False)))
                    except Exception:
                        continue

                # ─── Calibration warning ─────────────────────────────────
                if calibration_rows:
                    L_append(lines, "")
                    L_append(lines, "  ── ⚠️ CALIBRATION WARNINGS ──")
                    bad_calib = [r for r in calibration_rows if r[1] < 0.30]
                    if bad_calib:
                        L_append(lines, f"  🔴 {len(bad_calib)} استراتژی با WR < 30%:")
                        for name, wr_v, pen, blk in bad_calib[:10]:
                            flag = "🚫" if blk else "⚠️"
                            L_append(lines, f"     {flag} {name[:30]:<30} WR={wr_v:.1%} (Penalty={pen:.2f})")
                        L_append(lines, "  → این استراتژی‌ها باعث ضررهای مکرر می‌شوند.")
                        L_append(lines, "  → توصیه: فعال‌سازی Penalty Manager در .env")
                    else:
                        L_append(lines, "  ✅ همهٔ استراتژی‌ها WR >= 30%")

            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 3 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 4: Causal Loss Analysis
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 4 — CAUSAL LOSS ANALYSIS (تحلیل علّی)")
            L_append(lines, "-" * 100)
            try:
                causal_report = await generate_causal_loss_report(
                    engine=engine,
                    lookback_hours=168,
                    max_losses=30,
                )
                L_append(lines, causal_report)
            except Exception as causal_err:
                L_append(lines, f"⚠️ Causal report failed: {causal_err}")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 4 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 5: Weekly Progress
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 5 — WEEKLY PROGRESS (پیشرفت هفتگی)")
            L_append(lines, "-" * 100)
            try:
                weekly_report = await generate_weekly_progress_report(
                    engine=engine, weeks_back=4,
                )
                L_append(lines, weekly_report)
            except Exception as wk_err:
                L_append(lines, f"⚠️ Weekly report failed: {wk_err}")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 5 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 6: XGBoost Analysis
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 6 — XGBOOST MODEL ANALYSIS")
            L_append(lines, "-" * 100)
            xgb = None
            try:
                xgb = _get_component("xgboost_signal_generator")
            except Exception:
                pass
            if xgb is None:
                try:
                    xgb = _COMPONENT_CACHE.get("xgboost_signal_generator")
                except Exception:
                    xgb = None

            if xgb is None:
                L_append(lines, "❌ XGBoost NOT AVAILABLE")
            else:
                is_fitted = bool(getattr(xgb, "_is_fitted", False))
                stats = getattr(xgb, "_stats", {}) or {}
                metrics = getattr(xgb, "_training_metrics", {}) or {}
                L_append(lines, f"Model Trained       : {is_fitted}")
                L_append(lines, f"Calibration Factor  : {float(getattr(xgb, '_calibration_factor', 0.0) or 0.0):.4f}")
                L_append(lines, f"Total Predictions   : {stats.get('total_predictions', 0)}")
                L_append(lines, f"Total Signals       : {stats.get('total_signals', 0)}")
                L_append(lines, f"Win Rate            : {float(stats.get('win_rate', 0.0) or 0.0):.2%}")
                L_append(lines, f"Training Accuracy   : {float(stats.get('training_accuracy', 0.0) or 0.0):.2%}")
                L_append(lines, f"Fallback Count      : {stats.get('fallback_count', 0)}")
                if metrics:
                    L_append(lines, "")
                    L_append(lines, "  ── Latest Training Metrics ──")
                    L_append(lines, f"  Balanced Accuracy : {float(metrics.get('balanced_accuracy', 0.0) or 0.0):.2%}")
                    L_append(lines, f"  Precision BUY     : {float(metrics.get('prec_buy', 0.0) or 0.0):.2%}")
                    L_append(lines, f"  Precision SELL    : {float(metrics.get('prec_sell', 0.0) or 0.0):.2%}")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 6 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 7: CLE Status
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 7 — CONTINUOUS LEARNING ENGINE (CLE)")
            L_append(lines, "-" * 100)
            cle = getattr(engine, "continuous_learning_engine", None)
            if cle is None:
                L_append(lines, "❌ CLE is NONE — LEARNING COMPLETELY DISABLED")
            else:
                L_append(lines, f"CLE Running         : {getattr(cle, '_running', False)}")
                L_append(lines, f"CLE Loop Running    : {getattr(cle, '_loop_running', False)}")
                L_append(lines, f"CLE Healthy         : {getattr(cle, 'is_healthy', False)}")
                L_append(lines, f"Consecutive Fails   : {getattr(cle, '_loop_consecutive_failures', 0)}")
                L_append(lines, f"Degradation Mode    : {getattr(cle, '_degradation_mode_active', False)}")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 7 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 8: Market Context
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 8 — MARKET CONTEXT")
            L_append(lines, "-" * 100)
            sym = getattr(engine, "symbol", "BTCUSD")
            tf = getattr(engine, "timeframe", "1H")
            df = None
            try:
                if connector is not None:
                    df = await connector.get_historical_data(sym, tf, limit=500)
            except Exception:
                df = None
            if df is not None and len(df) >= 50:
                last_close = float(df["close"].iloc[-1])
                ret_1h = (last_close / float(df["close"].iloc[-2]) - 1.0) * 100
                L_append(lines, f"Last Close      : {last_close:.5f}")
                L_append(lines, f"Return (1 bar)  : {ret_1h:+.3f}%")
            else:
                L_append(lines, "⚠️ Could not fetch market data")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 8 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 9: Config
        # ═════════════════════════════════════════════════════════════════
        try:
            L_append(lines, "-" * 100)
            L_append(lines, "SECTION 9 — ACTIVE CONFIGURATION")
            L_append(lines, "-" * 100)
            try:
                min_conf_cfg = _MIN_CONFIDENCE_THRESHOLD
            except NameError:
                min_conf_cfg = 90.0
            L_append(lines, f"Min Confidence Threshold : {float(min_conf_cfg):.2f}%")
            L_append(lines, f"Max Positions            : {getattr(engine, 'max_positions', 'N/A')}")
            L_append(lines, f"Max Total Positions      : {getattr(engine, 'max_total_positions', 'N/A')}")
            L_append(lines, f"Max Risk Per Trade       : {float(getattr(engine, 'max_risk_per_trade', 0)):.2%}")
            L_append(lines, f"Stop Loss Base           : {float(getattr(engine, 'stop_loss', 0)):.2%}")
            L_append(lines, f"Trailing Stop %          : {float(getattr(engine, 'trailing_stop_pct', 0)):.2%}")
            L_append(lines, f"Model Enabled            : {getattr(engine, 'model_enabled', False)}")
            L_append(lines, f"Model Weight             : {float(getattr(engine, 'model_weight', 0)):.2%}")
            L_append(lines, f"TA Weight                : {float(getattr(engine, 'ta_weight', 0)):.2%}")
            L_append(lines, "")
        except Exception as e:
            L_append(lines, f"[SECTION 9 ERROR] {type(e).__name__}: {e}")
            L_append(lines, "")

        # ═════════════════════════════════════════════════════════════════
        # SECTION 10: Final Recommendations
        # ═════════════════════════════════════════════════════════════════
        try:

            L_append(lines, "")
            L_append(lines, "=" * 100)
            L_append(lines, f"END OF REPORT — {now.strftime('%Y-%m-%d %H:%M:%S')}")
            L_append(lines, "=" * 100)
        except Exception as e:
            L_append(lines, f"[SECTION 10 ERROR] {type(e).__name__}: {e}")

        report = "\n".join(lines)

        # ─── persist ─────────────────────────────────────────────────────
        write_ok = False
        try:
            AI_REPORT_DIR.mkdir(parents=True, exist_ok=True)
            tmp = AI_REPORT_FILE.with_suffix(".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                f.write(report)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except Exception:
                    pass
            os.replace(tmp, AI_REPORT_FILE)
            write_ok = True
        except Exception as write_err:
            logger.error(f"[{phase}] Report write error: {write_err}")

        if not write_ok:
            try:
                fallback = Path("TRADE") / "hourly_ai_report_fallback.txt"
                fallback.parent.mkdir(parents=True, exist_ok=True)
                with open(fallback, "w", encoding="utf-8") as f:
                    f.write(report)
            except Exception:
                pass

        try:
            AI_REPORT_ARCHIVE.mkdir(parents=True, exist_ok=True)
            archive_name = f"hourly_ai_report_{now.strftime('%Y%m%d_%H%M')}.txt"
            with open(AI_REPORT_ARCHIVE / archive_name, "w", encoding="utf-8") as f:
                f.write(report)
            archives = sorted(AI_REPORT_ARCHIVE.glob("hourly_ai_report_*.txt"))
            for old in archives[:-168]:
                try:
                    old.unlink()
                except Exception:
                    pass
        except Exception:
            pass

        logger.info(f"[{phase}] ✅ Report saved: {AI_REPORT_FILE} ({len(report)} bytes)")
        return report

    except Exception as e:
        logger.error(f"[{phase}] ❌ Fatal: {e}", exc_info=True)
        return None

async def ai_hourly_report_loop(
    engine: "UnifiedTradingEngine",
    connector: "VTVCOConnector",
    economic_calendar=None,
    interval_seconds: int = 3600,
):
    """
    حلقهٔ گزارش ساعتی AI — V3.0
    شامل: گزارش اصلی + گزارش علّی جداگانه + گزارش پیشرفت هفتگی
    """
    phase = "AI_HOURLY_LOOP_V3"
    safe_interval = max(300, int(interval_seconds))
    logger.info(f"[{phase}] 🚀 Starting hourly AI report loop (interval={safe_interval}s)")

    try:
        await asyncio.sleep(300)
    except asyncio.CancelledError:
        return

    cycle = 0
    consecutive_failures = 0
    max_consecutive_failures = 3

    while getattr(engine, "_running", False):
        try:
            cycle += 1
            logger.info(f"[{phase}] 📊 Generating AI report #{cycle}...")

            report = await generate_ai_analysis_report(
                engine=engine,
                connector=connector,
                economic_calendar=economic_calendar,
            )

            if report is None:
                consecutive_failures += 1
                logger.error(
                    f"[{phase}] ❌ Report #{cycle} returned None "
                    f"(failures: {consecutive_failures}/{max_consecutive_failures})"
                )
                if consecutive_failures >= max_consecutive_failures:
                    logger.critical(
                        f"[{phase}] 🚨 {consecutive_failures} consecutive failures — "
                        f"investigate generate_ai_analysis_report"
                    )
            else:
                consecutive_failures = 0

                # ─── send main report ────────────────────────────────────
                try:
                    if hasattr(tel_log, "send_document"):
                        tel_log.send_document(
                            str(AI_REPORT_FILE),
                            caption=f"📊 AI Hourly Report #{cycle}"
                        )
                    elif hasattr(tel_log, "trade"):
                        CHUNK = 3500
                        header = (
                            f"📊 *AI HOURLY REPORT #{cycle}* — "
                            f"{datetime.now().strftime('%H:%M')}\n"
                        )
                        try:
                            tel_log.trade(header)
                        except Exception:
                            pass
                        for i in range(0, len(report), CHUNK):
                            chunk = report[i:i + CHUNK]
                            try:
                                tel_log.trade(f"```\n{chunk}\n```")
                            except Exception:
                                pass
                            await asyncio.sleep(1.5)
                    logger.info(f"[{phase}] ✅ Report #{cycle} sent")
                except Exception as send_err:
                    logger.error(f"[{phase}] Send error: {send_err}")

                # ─── send causal report separately ───────────────────────
                try:
                    causal = await generate_causal_loss_report(
                        engine=engine, lookback_hours=168, max_losses=30,
                    )
                    if causal and hasattr(tel_log, "trade"):
                        await asyncio.sleep(2)
                        tel_log.trade(f"```\n{causal[:3500]}\n```")
                        logger.info(f"[{phase}] ✅ Causal report sent")
                except Exception as causal_err:
                    logger.warning(f"[{phase}] Causal report error: {causal_err}")

            # ─── sleep until next cycle ──────────────────────────────────
            for _ in range(safe_interval):
                if not getattr(engine, "_running", False):
                    break
                await asyncio.sleep(1)

        except asyncio.CancelledError:
            logger.info(f"[{phase}] 🛑 Loop cancelled")
            break
        except Exception as e:
            consecutive_failures += 1
            logger.error(f"[{phase}] ❌ Error: {e}", exc_info=True)
            await asyncio.sleep(300)

    logger.info(f"[{phase}] 🛑 Loop stopped")
    
    
async def _daily_cle_report_loop(engine: "UnifiedTradingEngine") -> None:
    """
    حلقه تولید گزارش روزانه CLE (هر 24 ساعت).

    ✅ FIXED V2:
        • دریافت نمونه‌ی engine به‌صورت پارامتر (رفع خطای missing 'self')
        • تبدیل به حلقه‌ی واقعی با بررسی `engine._running`
        • فراخوانی صحیح `engine._generate_daily_cle_report()`
        • مدیریت صحیح CancelledError
    """
    phase = "DAILY_CLE_REPORT_LOOP"
    logger.info(f"[{phase}] 🚀 Starting daily CLE report loop")

    try:
        while getattr(engine, '_running', False):
            await asyncio.sleep(86400)  # 24 ساعت

            if not getattr(engine, '_running', False):
                break

            try:
                await engine._generate_daily_cle_report()
            except asyncio.CancelledError:
                raise
            except Exception as report_err:
                logger.error(
                    f"[{phase}] ❌ Report generation failed: {report_err}",
                    exc_info=True,
                )
                # ادامه‌ی حلقه پس از خطای یک گزارش

    except asyncio.CancelledError:
        logger.info(f"[{phase}] 🛑 Daily CLE report loop cancelled")
        raise
    except Exception as e:
        logger.error(f"[{phase}] ❌ Critical loop error: {e}", exc_info=True)
            
